def pegasos_svm(X, y, C=1.0, max_iter=100):
    w = np.zeros(X.shape[1])
    for t in range(1, max_iter + 1):
        eta = 1.0 / (C * t)
        for i in range(len(X)):
            if y[i] * np.dot(w, X[i]) < 1:
                w = (1 - eta * C) * w + eta * y[i] * X[i]
            else:
                w = (1 - eta * C) * w
    return w

